from collections import Counter

def word_freq(words):
    return dict(Counter(words))

def dedupe(items):
    seen = set()
    out = []
    for x in items:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

from collections import defaultdict

def group_names(records):
    out = defaultdict(list)
    for r in records:
        out[r['dept']].append(r['name'])
    return dict(out)

import re

def parse_log(line):
    m = re.match(r'(\S+) (\S+) user=(\S+) msg=(.+)', line)
    if not m: return None
    return {'ts': m[1], 'level': m[2], 'user': m[3], 'msg': m[4]}

